# area: self_classmethods
# hypothesis: a Self-typed classmethod and property, plus a value read through a custom descriptor, should bind to Child, while the descriptor's declared return type stays Base.
# spec: PEP 673 - Self refers to the type of the receiver at the call or access site.
from typing import Self, reveal_type


class Describe:
    def __get__(self, obj: 'Base | None', owner: type['Base']) -> 'Base':
        return obj if obj is not None else owner()


class Base:
    label = Describe()

    class Inner:
        def clone(self) -> 'Base.Inner':
            return self

    @classmethod
    def make(cls) -> Self:
        return cls()

    @property
    def me(self) -> Self:
        return self


class Child(Base):
    kind: str = 'child'


reveal_type(Child.make())
reveal_type(Child().me)
reveal_type(Child().label)
reveal_type(Base.Inner().clone())
Child().label.make()
